import { ArrowRight, Bell, CheckCircle2, ChevronRight, CircleDot, ClipboardList, Clock3, Edit3, Eye, Filter, LockKeyhole, MapPin, Navigation, Package, Phone, Plus, RefreshCw, Search, Settings, ShieldCheck, Truck, UserRound, Wallet, X } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { acceptDelivery, changePassword, createDriver, createVehicle, deleteDriver, deleteVehicle, getDeliveries, getDrivers, getNotifications, getTracking, getVehicles, markNotificationRead, updateDriver, updateVehicle } from '../../services/api';
import { getProductImage } from '../../utils/productImages';

const labels = { AVAILABLE: 'Available', ACCEPTED: 'Accepted', VEHICLE_ASSIGNED: 'Assigned', PICKED_UP: 'Picked up', IN_TRANSIT: 'In transit', OUT_FOR_DELIVERY: 'Out for delivery', DELIVERED: 'Delivered' };
const tabs = ['ALL', 'AVAILABLE', 'ACCEPTED', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'DELIVERED'];

export default function LogisticsFeaturePage() {
    const requestedView = useLocation().pathname.split('/')[2] || 'deliveries';
    const view = requestedView === 'my-deliveries' ? 'deliveries' : requestedView;
    const [data, setData] = useState({ deliveries: [], vehicles: [], drivers: [], notifications: [], loading: true, error: '' });
    const [query, setQuery] = useState('');
    const [filter, setFilter] = useState('ALL');
    const [selected, setSelected] = useState(null);
    const [notice, setNotice] = useState('');

    async function load() {
        setData((current) => ({ ...current, loading: true, error: '' }));
        try {
            const [deliveryResult, vehicleResult, driverResult] = await Promise.all([getDeliveries(), getVehicles(), getDrivers()]);
            let notifications = [];
            try { notifications = (await getNotifications()).items || []; } catch (_) { notifications = []; }
            setData({ deliveries: deliveryResult.items || [], vehicles: vehicleResult.items || [], drivers: driverResult.items || [], notifications, loading: false, error: '' });
        } catch (requestError) {
            setData((current) => ({ ...current, loading: false, error: requestError instanceof Error ? requestError.message : 'Unable to load logistics data' }));
        }
    }

    useEffect(() => { load(); }, []);

    const filteredDeliveries = useMemo(() => data.deliveries.filter((delivery) => delivery.status === 'AVAILABLE').filter((delivery) => {
        const priority = Number(delivery.order?.total_amount || 0) >= 5000 || delivery.priority === 'HIGH';
        const matchesFilter = filter === 'ALL' || (filter === 'PENDING' && ['AVAILABLE', 'ACCEPTED'].includes(delivery.status)) || (filter === 'HIGH_PRIORITY' && priority);
        const text = `${delivery.order_id} ${delivery.pickup_location} ${delivery.destination}`.toLowerCase();
        return matchesFilter && text.includes(query.toLowerCase());
    }), [data.deliveries, filter, query]);
    useEffect(() => { if (!selected && filteredDeliveries[0]) setSelected(filteredDeliveries[0]); }, [filteredDeliveries, selected]);

    const title = requestedView === 'my-deliveries' ? 'My deliveries' : ({ deliveries: 'Available deliveries', vehicles: 'Vehicle management', drivers: 'Driver management', tracking: 'Delivery tracking', earnings: 'Earnings overview', notifications: 'Notifications', settings: 'Workspace settings' }[view] || 'Logistics workspace');
    const subtitle = { deliveries: 'Browse and accept new delivery requests.', vehicles: 'Keep every vehicle ready for the next handoff.', drivers: 'Manage your dispatch roster and availability.', tracking: 'Follow every active handoff from pickup to delivery.', earnings: 'See your completed delivery performance at a glance.', notifications: 'Stay current on assignments and route changes.', settings: 'Manage account security and dispatch preferences.' }[view] || '';

    if (view === 'vehicles') return <ResourceManagementPage type="vehicles" items={data.vehicles} loading={data.loading} error={data.error} onReload={load} onNotice={setNotice} notice={notice} />;
    if (view === 'drivers') return <ResourceManagementPage type="drivers" items={data.drivers} loading={data.loading} error={data.error} onReload={load} onNotice={setNotice} notice={notice} />;
    if (view === 'tracking') return <LogisticsTrackingPage deliveries={data.deliveries} loading={data.loading} error={data.error} />;
    if (view === 'earnings') return <LogisticsEarningsPage deliveries={data.deliveries} loading={data.loading} />;
    if (view === 'notifications') return <NotificationsView items={data.notifications} loading={data.loading} onReload={load} />;
    if (view === 'settings') return <SettingsView onNotice={setNotice} notice={notice} />;
    if (requestedView === 'my-deliveries') return <MyDeliveriesView deliveries={data.deliveries.filter((delivery) => delivery.status !== 'AVAILABLE')} loading={data.loading} error={data.error} onReload={load} />;

    async function accept(id) { try { await acceptDelivery(id); setNotice('Delivery accepted.'); await load(); } catch (requestError) { setData((current) => ({ ...current, error: requestError instanceof Error ? requestError.message : 'Unable to accept delivery' })); } }
    return <main className="logistics-feature-page logistics-available-page"><div className="logistics-feature-container"><header className="logistics-available-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker"><Package size={14} /> DELIVERY DESK</p><h1>{title}</h1><p>{subtitle}</p></div><button type="button" className="logistics-refresh" onClick={load} disabled={data.loading}><RefreshCw size={15} /> Refresh</button></header>{notice && <p className="logistics-feature-notice" role="status"><CheckCircle2 size={15} />{notice}</p>}{data.error && <p className="logistics-feature-error" role="alert">{data.error}</p>}<div className="logistics-delivery-workspace"><section className="logistics-delivery-feed"><div className="logistics-delivery-feed-head"><div><span>DELIVERY REQUESTS</span><h2>{data.deliveries.filter((delivery) => delivery.status === 'AVAILABLE').length} available deliveries</h2></div><label className="logistics-list-search"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search orders" /></label></div><div className="logistics-filter-tabs">{[['ALL', 'All'], ['PENDING', 'Pending'], ['HIGH_PRIORITY', 'High Priority']].map(([value, label]) => <button type="button" className={filter === value ? 'is-active' : ''} onClick={() => setFilter(value)} key={value}>{label}</button>)}</div><div className="logistics-feature-list">{data.loading ? <div className="logistics-feature-loading" /> : filteredDeliveries.map((delivery) => <DeliveryRow delivery={delivery} selected={selected?.id === delivery.id} key={delivery.id} onSelect={setSelected} onAccept={accept} />)}{!data.loading && filteredDeliveries.length === 0 && <EmptyState icon={Package} title="No available deliveries" copy="New delivery requests will appear here when orders are ready for dispatch." />}</div></section><DeliveryDetailsPanel delivery={selected} onAccept={accept} /></div></div></main>;
}

function FeatureHeader({ title, subtitle, icon: Icon, action }) { return <header className="logistics-feature-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker"><Icon size={14} /> LOGISTICS WORKSPACE</p><h1>{title}</h1><p>{subtitle}</p></div><div className="logistics-feature-header-action">{action}</div></header>; }
function MyDeliveriesView({ deliveries, loading, error, onReload }) {
    const [filter, setFilter] = useState('ALL');
    const [query, setQuery] = useState('');
    const [selected, setSelected] = useState(null);
    const filters = [['ALL', 'All'], ['ASSIGNED', 'Assigned'], ['IN_TRANSIT', 'In Transit'], ['DELIVERED', 'Delivered'], ['CANCELLED', 'Cancelled']];
    const visible = deliveries.filter((delivery) => {
        const status = delivery.status || '';
        const matchesFilter = filter === 'ALL' || (filter === 'ASSIGNED' && ['ACCEPTED', 'VEHICLE_ASSIGNED'].includes(status)) || (filter === 'IN_TRANSIT' && ['PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY'].includes(status)) || status === filter;
        return matchesFilter && `${delivery.order_id} ${delivery.pickup_location} ${delivery.destination} ${delivery.order?.items?.[0]?.product?.name || ''}`.toLowerCase().includes(query.toLowerCase());
    });
    return <main className="logistics-feature-page logistics-my-deliveries-page"><div className="logistics-feature-container"><header className="logistics-my-deliveries-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker"><ClipboardIcon /> MY DELIVERIES</p><h1>My deliveries</h1><p>Track every delivery currently assigned to your logistics team.</p></div><button type="button" className="logistics-refresh" onClick={onReload} disabled={loading}><RefreshCw size={15} /> Refresh</button></header>{error && <p className="logistics-feature-error" role="alert">{error}</p>}<section className="logistics-my-deliveries-panel"><div className="logistics-my-deliveries-panel-head"><div><span>DELIVERY HISTORY</span><h2>{visible.length} deliveries</h2></div><label className="logistics-list-search"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search deliveries" /></label></div><div className="logistics-my-deliveries-tabs">{filters.map(([value, label]) => <button type="button" className={filter === value ? 'is-active' : ''} onClick={() => setFilter(value)} key={value}>{label}</button>)}</div><div className="logistics-my-deliveries-table"><div className="logistics-my-deliveries-table-head"><span>Order ID</span><span>Product</span><span>Status</span><span>Actions</span></div>{loading ? <div className="logistics-feature-loading" /> : visible.map((delivery) => <MyDeliveryRow delivery={delivery} onView={setSelected} key={delivery.id} />)}{!loading && visible.length === 0 && <EmptyState icon={Package} title="No deliveries in this view" copy="Accepted delivery requests will appear here for tracking." />}</div></section></div>{selected && <DeliveryDetails delivery={selected} onClose={() => setSelected(null)} />}</main>;
}
function MyDeliveryRow({ delivery, onView }) { const item = delivery.order?.items?.[0]; const productName = item?.product?.name || item?.product_name || 'Produce order'; const status = labels[delivery.status] || delivery.status; const isDelivered = delivery.status === 'DELIVERED'; return <div className="logistics-my-delivery-row"><span className="logistics-my-order-id">FD{delivery.order_id}</span><div className="logistics-my-product"><img src={getProductImage({ name: productName })} alt="" /><span><strong>{productName}</strong><small>{item?.quantity || 'Produce'} kg</small></span></div><span className={`logistics-my-status status-${delivery.status.toLowerCase()}`}><CircleDot size={11} />{status}</span><div className="logistics-my-actions">{!isDelivered && <Link to={`/logistics/tracking?order=${delivery.order_id}`} className="logistics-track-link"><Navigation size={13} /> Track</Link>}<button type="button" className="logistics-view-link" onClick={() => onView(delivery)}>{isDelivered ? 'View' : 'Details'} <ChevronRight size={13} /></button></div></div>; }
function ClipboardIcon() { return <ClipboardList size={14} />; }
function DeliveryRow({ delivery, selected, onSelect, onAccept }) { const priority = Number(delivery.order?.total_amount || 0) >= 5000 || delivery.priority === 'HIGH'; return <article className={`logistics-feature-row ${selected ? 'is-selected' : ''}`} onClick={() => onSelect(delivery)}><div className="logistics-feature-row-icon"><Package size={18} /></div><div className="logistics-feature-row-main"><div className="logistics-feature-row-top"><span>ORDER FD{delivery.order_id}</span><span className="logistics-row-badges">{priority && <b className="logistics-priority-pill">High Priority</b>}<b className={`logistics-status-pill status-${delivery.status.toLowerCase()}`}>{labels[delivery.status] || delivery.status}</b></span></div><h2>{delivery.pickup_location} <ChevronRight size={15} /> {delivery.destination}</h2><p>{delivery.order?.total_amount ? `₹${Number(delivery.order.total_amount).toLocaleString('en-IN')} · ` : ''}{delivery.vehicle ? `${delivery.vehicle.registration_number} · ${delivery.driver?.full_name || 'Driver assigned'}` : 'Vehicle and driver pending'}</p></div><div className="logistics-row-actions">{delivery.status === 'AVAILABLE' && <button type="button" className="logistics-accept-button" onClick={(event) => { event.stopPropagation(); onAccept(delivery.id); }}>Accept</button>}<button type="button" className="logistics-row-action" onClick={() => onSelect(delivery)}><Eye size={15} /> View</button></div></article>; }
function DeliveryDetailsPanel({ delivery, onAccept }) { if (!delivery) return <aside className="logistics-order-details"><div className="logistics-order-details-empty"><Package size={28} /><h2>Order details</h2><p>Select a delivery request to review the pickup, destination, and handoff requirements.</p></div></aside>; return <aside className="logistics-order-details"><div className="logistics-order-details-head"><div><span>ORDER FD{delivery.order_id}</span><h2>Order details</h2></div><b className={`logistics-status-pill status-${delivery.status.toLowerCase()}`}>{labels[delivery.status] || delivery.status}</b></div><div className="logistics-order-product"><span className="logistics-product-orb"><Package size={18} /></span><div><strong>{delivery.order?.items?.[0]?.product?.name || 'Fresh produce order'}</strong><small>{delivery.order?.items?.[0]?.quantity || '1,500'} kg · Grade A</small></div><b>₹{Number(delivery.order?.total_amount || 4500).toLocaleString('en-IN')}</b></div><div className="logistics-order-route"><div><span className="logistics-route-dot is-pickup"/><div><small>Pickup location</small><strong>{delivery.pickup_location}</strong><p>Farm partner collection point</p></div></div><div><span className="logistics-route-dot is-dropoff"/><div><small>Drop location</small><strong>{delivery.destination}</strong><p>Customer or depot handoff</p></div></div></div><div className="logistics-order-requirements"><div><small>VEHICLE REQUIRED</small><strong>{delivery.vehicle?.vehicle_type || 'Large vehicle'}</strong></div><div><small>ESTIMATED DISTANCE</small><strong>— km</strong></div></div><div className="logistics-order-value"><span>Order value</span><strong>₹{Number(delivery.order?.total_amount || 4500).toLocaleString('en-IN')}</strong></div>{delivery.status === 'AVAILABLE' && <button type="button" className="logistics-order-accept" onClick={() => onAccept(delivery.id)}>Accept delivery <ArrowRightIcon /></button>}{delivery.status !== 'AVAILABLE' && <Link className="logistics-order-track" to={`/tracking/${delivery.order_id}`}><Navigation size={15} /> View tracking</Link>}</aside>; }
function DeliveryDetails({ delivery, onClose }) { return <div className="logistics-modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><aside className="logistics-modal" role="dialog" aria-modal="true"><button className="logistics-modal-close" type="button" onClick={onClose} aria-label="Close delivery details"><X size={18} /></button><p className="logistics-feature-kicker">ORDER FD{delivery.order_id}</p><h2>Delivery details</h2><span className={`logistics-status-pill status-${delivery.status.toLowerCase()}`}>{labels[delivery.status] || delivery.status}</span><div className="logistics-detail-grid"><div><small>PICKUP</small><strong>{delivery.pickup_location}</strong></div><div><small>DESTINATION</small><strong>{delivery.destination}</strong></div><div><small>VEHICLE</small><strong>{delivery.vehicle?.registration_number || 'Not assigned'}</strong></div><div><small>DRIVER</small><strong>{delivery.driver?.full_name || 'Not assigned'}</strong></div></div><Link className="logistics-modal-link" to={`/logistics/tracking?order=${delivery.order_id}`} onClick={onClose}><Navigation size={15} /> Open tracking view</Link></aside></div>; }

function ResourceManagementPage({ type, items, loading, error, onReload, onNotice, notice }) {
    const isVehicle = type === 'vehicles';
    const [filter, setFilter] = useState('ALL');
    const [query, setQuery] = useState('');
    const [modal, setModal] = useState(null);
    const [form, setForm] = useState(isVehicle ? { registration_number: '', vehicle_type: 'Large Truck', capacity_kg: 1000 } : { full_name: '', phone: '', license_number: '' });
    const tabs = isVehicle ? [['ALL', 'All Vehicles'], ['ACTIVE', 'Active'], ['MAINTENANCE', 'Maintenance'], ['INACTIVE', 'Inactive']] : [['ALL', 'All Drivers'], ['ACTIVE', 'Active'], ['ON_TRIP', 'On Trip'], ['INACTIVE', 'Inactive']];
    const filtered = items.filter((item) => { const matchesSearch = `${item.registration_number || ''} ${item.vehicle_type || ''} ${item.full_name || ''} ${item.phone || ''} ${item.license_number || ''}`.toLowerCase().includes(query.toLowerCase()); const matchesFilter = filter === 'ALL' || (filter === 'ACTIVE' && item.is_available) || (filter === 'INACTIVE' && !item.is_available) || (filter === 'MAINTENANCE' && item.status === 'MAINTENANCE') || (filter === 'ON_TRIP' && !item.is_available); return matchesSearch && matchesFilter; });
    const counts = { total: items.length, active: items.filter((item) => item.is_available).length, busy: items.filter((item) => !item.is_available).length, maintenance: items.filter((item) => item.status === 'MAINTENANCE').length };
    const title = isVehicle ? 'Vehicle management' : 'Driver management';
    async function save(event) { event.preventDefault(); try { if (modal === 'add') await (isVehicle ? createVehicle(form) : createDriver(form)); else await (isVehicle ? updateVehicle(modal.id, { vehicle_type: form.vehicle_type, capacity_kg: Number(form.capacity_kg) }) : updateDriver(modal.id, { full_name: form.full_name, phone: form.phone })); setModal(null); onNotice(`${isVehicle ? 'Vehicle' : 'Driver'} ${modal === 'add' ? 'added' : 'updated'} successfully.`); await onReload(); } catch (requestError) { onNotice(requestError instanceof Error ? requestError.message : `Unable to save ${isVehicle ? 'vehicle' : 'driver'}`); } }
    async function remove(item) { if (!window.confirm(`Remove ${isVehicle ? item.registration_number : item.full_name}?`)) return; try { await (isVehicle ? deleteVehicle(item.id) : deleteDriver(item.id)); onNotice(`${isVehicle ? 'Vehicle' : 'Driver'} removed.`); await onReload(); } catch (requestError) { onNotice(requestError instanceof Error ? requestError.message : 'Unable to remove resource'); } }
    function openAdd() { setForm(isVehicle ? { registration_number: '', vehicle_type: 'Large Truck', capacity_kg: 1000 } : { full_name: '', phone: '', license_number: '' }); setModal('add'); }
    function openEdit(item) { setForm(item); setModal(item); }
    return <main className="logistics-feature-page logistics-resource-page"><div className="logistics-feature-container"><header className="logistics-resource-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker">{isVehicle ? <Truck size={14} /> : <UserRound size={14} />} {isVehicle ? 'FLEET MANAGEMENT' : 'DRIVER MANAGEMENT'}</p><h1>{title}</h1><p>{isVehicle ? 'Manage your fleet and keep every vehicle ready for dispatch.' : 'Manage drivers, availability, and the people behind every handoff.'}</p></div><div className="logistics-resource-header-actions"><button type="button" className="logistics-refresh" onClick={onReload} disabled={loading}><RefreshCw size={15} /> Refresh</button><button type="button" className="logistics-resource-add" onClick={openAdd}><Plus size={15} /> Add {isVehicle ? 'vehicle' : 'driver'}</button></div></header>{error && <p className="logistics-feature-error" role="alert">{error}</p>}{notice && <p className="logistics-feature-notice" role="status"><CheckCircle2 size={15} />{notice}</p>}<section className="logistics-resource-summary"><ResourceStat label={`Total ${isVehicle ? 'vehicles' : 'drivers'}`} value={counts.total} tone="blue" icon={isVehicle ? Truck : UserRound} /><ResourceStat label="Active" value={counts.active} tone="green" icon={CheckCircle2} /><ResourceStat label={isVehicle ? 'Maintenance' : 'On trip'} value={isVehicle ? counts.maintenance : counts.busy} tone="orange" icon={isVehicle ? Settings : Navigation} /><ResourceStat label="Inactive" value={counts.busy} tone="grey" icon={Clock3} /></section><section className="logistics-resource-management-panel"><div className="logistics-resource-panel-head"><div><span>{isVehicle ? 'FLEET REGISTER' : 'DRIVER ROSTER'}</span><h2>{filtered.length} {isVehicle ? 'vehicles' : 'drivers'}</h2></div><label className="logistics-list-search"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={`Search ${isVehicle ? 'vehicles' : 'drivers'}`} /></label></div><div className="logistics-resource-tabs">{tabs.map(([value, label]) => <button type="button" className={filter === value ? 'is-active' : ''} onClick={() => setFilter(value)} key={value}>{label}</button>)}</div><div className="logistics-resource-management-table"><div className="logistics-resource-management-head"><span>{isVehicle ? 'Vehicle No.' : 'Name'}</span><span>{isVehicle ? 'Type' : 'Phone'}</span><span>{isVehicle ? 'Capacity' : 'License No.'}</span><span>Status</span><span>Actions</span></div>{loading ? <div className="logistics-feature-loading" /> : filtered.map((item) => <div className="logistics-resource-management-row" key={item.id}><strong>{isVehicle ? item.registration_number : item.full_name}</strong><span>{isVehicle ? item.vehicle_type : item.phone}</span><span>{isVehicle ? `${item.capacity_kg} kg` : item.license_number}</span><b className={item.is_available ? 'is-ready' : 'is-busy'}>{item.is_available ? 'ACTIVE' : item.status === 'MAINTENANCE' ? 'MAINTENANCE' : 'ON TRIP'}</b><div><button type="button" onClick={() => openEdit(item)} aria-label={`Edit ${isVehicle ? item.registration_number : item.full_name}`}><Edit3 size={14} /></button><button type="button" onClick={() => remove(item)} aria-label={`Remove ${isVehicle ? item.registration_number : item.full_name}`}><X size={14} /></button></div></div>)}{!loading && !filtered.length && <EmptyState icon={isVehicle ? Truck : UserRound} title={`No ${isVehicle ? 'vehicles' : 'drivers'} found`} copy={`Add a ${isVehicle ? 'vehicle' : 'driver'} to build your dispatch resources.`} />}</div></section></div>{modal && <div className="logistics-modal-backdrop"><form className="logistics-modal logistics-resource-modal" onSubmit={save}><button className="logistics-modal-close" type="button" onClick={() => setModal(null)} aria-label="Close resource form"><X size={18} /></button><p className="logistics-feature-kicker">{modal === 'add' ? 'ADD RESOURCE' : 'EDIT RESOURCE'}</p><h2>{modal === 'add' ? `Add ${isVehicle ? 'vehicle' : 'driver'}` : `Edit ${isVehicle ? modal.registration_number : modal.full_name}`}</h2>{isVehicle ? <><label>Registration number<input value={form.registration_number || ''} onChange={(event) => setForm({ ...form, registration_number: event.target.value })} required disabled={modal !== 'add'} /></label><label>Vehicle type<input value={form.vehicle_type || ''} onChange={(event) => setForm({ ...form, vehicle_type: event.target.value })} required /></label><label>Capacity in kg<input type="number" min="1" value={form.capacity_kg || ''} onChange={(event) => setForm({ ...form, capacity_kg: event.target.value })} required /></label></> : <><label>Full name<input value={form.full_name || ''} onChange={(event) => setForm({ ...form, full_name: event.target.value })} required /></label><label>Phone<input value={form.phone || ''} onChange={(event) => setForm({ ...form, phone: event.target.value })} required /></label><label>License number<input value={form.license_number || ''} onChange={(event) => setForm({ ...form, license_number: event.target.value })} required disabled={modal !== 'add'} /></label></>}<button className="logistics-primary-button" type="submit">{modal === 'add' ? 'Add resource' : 'Save changes'}</button></form></div>}</main>;
}
function ResourceStat({ label, value, tone, icon: Icon }) { return <div className={`logistics-resource-stat tone-${tone}`}><span><Icon size={16} /></span><div><small>{label}</small><strong>{value}</strong></div></div>; }

function ResourcePage({ type, items, loading, error, onReload, onNotice, notice }) { const isVehicle = type === 'vehicles'; const [editing, setEditing] = useState(null); const [form, setForm] = useState({}); const save = async (event) => { event.preventDefault(); try { await (isVehicle ? updateVehicle(editing.id, { vehicle_type: form.vehicle_type, capacity_kg: Number(form.capacity_kg) }) : updateDriver(editing.id, { full_name: form.full_name, phone: form.phone })); setEditing(null); onNotice('Resource updated.'); onReload(); } catch (requestError) { onNotice(requestError instanceof Error ? requestError.message : 'Unable to update resource'); } }; return <main className="logistics-feature-page"><div className="logistics-feature-container"><FeatureHeader title={isVehicle ? 'Vehicle management' : 'Driver management'} subtitle={isVehicle ? 'Keep every vehicle ready for the next handoff.' : 'Manage your dispatch roster and availability.'} icon={isVehicle ? Truck : UserRound} action={<button type="button" className="logistics-refresh" onClick={onReload}><RefreshCw size={15} /> Refresh</button>} />{error && <p className="logistics-feature-error" role="alert">{error}</p>}{notice && <p className="logistics-feature-notice" role="status"><CheckCircle2 size={15} />{notice}</p>}<section className="logistics-resource-table"><div className="logistics-resource-table-head"><span>{isVehicle ? 'Vehicle' : 'Driver'}</span><span>Details</span><span>Status</span><span>Action</span></div>{loading ? <div className="logistics-feature-loading" /> : items.map((item) => <div className="logistics-resource-table-row" key={item.id}><strong>{isVehicle ? item.registration_number : item.full_name}</strong><span>{isVehicle ? `${item.vehicle_type} · ${item.capacity_kg} kg` : `${item.phone} · ${item.license_number}`}</span><b className={item.is_available ? 'is-ready' : 'is-busy'}>{item.is_available ? 'ACTIVE' : 'ASSIGNED'}</b><button type="button" onClick={() => { setEditing(item); setForm(item); }}><Edit3 size={14} /> Edit</button></div>)}{!loading && !items.length && <EmptyState icon={isVehicle ? Truck : UserRound} title={`No ${type} registered`} copy={`Add ${isVehicle ? 'a vehicle' : 'a driver'} from the Operations dashboard to build your dispatch team.`} />}</section></div>{editing && <div className="logistics-modal-backdrop"><form className="logistics-modal logistics-edit-form" onSubmit={save}><button className="logistics-modal-close" type="button" onClick={() => setEditing(null)} aria-label="Close edit form"><X size={18} /></button><p className="logistics-feature-kicker">EDIT RESOURCE</p><h2>{isVehicle ? editing.registration_number : editing.full_name}</h2>{isVehicle ? <><label>Vehicle type<input value={form.vehicle_type || ''} onChange={(event) => setForm({ ...form, vehicle_type: event.target.value })} /></label><label>Capacity in kg<input type="number" min="1" value={form.capacity_kg || ''} onChange={(event) => setForm({ ...form, capacity_kg: event.target.value })} /></label></> : <><label>Full name<input value={form.full_name || ''} onChange={(event) => setForm({ ...form, full_name: event.target.value })} /></label><label>Phone<input value={form.phone || ''} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></label></>}<button className="logistics-primary-button" type="submit">Save changes</button></form></div>}</main>; }

function LogisticsTrackingPage({ deliveries, loading, error }) { const active = deliveries.filter((item) => item.status !== 'DELIVERED'); const location = useLocation(); const requestedOrder = new URLSearchParams(location.search).get('order'); const [selected, setSelected] = useState(null); const [tracking, setTracking] = useState(null); const [refreshing, setRefreshing] = useState(false); useEffect(() => { const next = active.find((item) => String(item.order_id) === requestedOrder) || active[0] || null; setSelected(next); }, [requestedOrder, deliveries]); useEffect(() => { if (selected) loadTracking(selected); }, [selected]); async function loadTracking(delivery) { setRefreshing(true); try { const result = await getTracking(delivery.order_id); setTracking(result.delivery); } catch (_) { setTracking(delivery); } finally { setRefreshing(false); } } const events = tracking?.events || tracking?.tracking_events || [{ id: 'current', status: tracking?.status, note: 'Current delivery status' }]; return <main className="logistics-feature-page logistics-tracking-reference-page"><div className="logistics-feature-container"><header className="logistics-tracking-reference-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker"><Navigation size={14}/> LIVE DELIVERY TRACKING</p><h1>Delivery Tracking</h1><p>Follow every handoff from pickup to customer delivery.</p></div><button type="button" className="logistics-refresh" onClick={() => selected && loadTracking(selected)} disabled={refreshing}><RefreshCw size={15}/> {refreshing ? 'Refreshing' : 'Refresh'}</button></header>{error && <p className="logistics-feature-error" role="alert">{error}</p>}<div className="logistics-tracking-reference-grid"><section className="logistics-tracking-timeline-card"><div className="logistics-tracking-order-head"><div><span>ORDER FD{tracking?.order_id || selected?.order_id || '—'}</span><h2>{tracking?.destination || selected?.destination || 'Select a delivery'}</h2></div>{tracking && <b className={`logistics-status-pill status-${String(tracking.status).toLowerCase()}`}>{labels[tracking.status] || tracking.status}</b>}</div>{loading ? <div className="logistics-feature-loading" /> : active.map((delivery) => <button className={`logistics-tracking-order-select ${selected?.id === delivery.id ? 'is-selected' : ''}`} type="button" onClick={() => setSelected(delivery)} key={delivery.id}><span>FD{delivery.order_id}</span><strong>{delivery.pickup_location} <ChevronRight size={13}/> {delivery.destination}</strong><small>{labels[delivery.status] || delivery.status}</small></button>)}{tracking ? <div className="logistics-reference-timeline">{events.map((event, index) => <div className={index === events.length - 1 ? 'is-current' : ''} key={event.id || `${event.status}-${index}`}><span className="logistics-timeline-marker">{index === events.length - 1 ? <Truck size={13}/> : <CheckCircle2 size={13}/>}</span><div><strong>{labels[event.status] || event.status}</strong><small>{event.note || 'Delivery milestone completed'}</small><time>{index === events.length - 1 ? 'Current status' : 'Completed'}</time></div></div>)}</div> : !loading && <EmptyState icon={Navigation} title="No active delivery selected" copy="Select a delivery to see its complete tracking timeline." />}</section><section className="logistics-tracking-live-card">{tracking ? <><div className="logistics-tracking-map-large"><div className="logistics-live-road road-one"/><div className="logistics-live-road road-two"/><span className="logistics-live-pin live-start">A</span><span className="logistics-live-pin live-end">B</span><span className="logistics-live-truck"><Truck size={18}/></span><span className="logistics-live-map-label label-a">{tracking.pickup_location}</span><span className="logistics-live-map-label label-b">{tracking.destination}</span><div className="logistics-live-map-legend"><i/> Vehicle route</div></div><div className="logistics-live-location"><div><span><MapPin size={15}/></span><div><small>LIVE LOCATION</small><strong>{tracking.vehicle?.registration_number || 'Vehicle in transit'}</strong><p>{tracking.destination}</p></div></div><a href={tracking.driver?.phone ? `tel:${tracking.driver.phone}` : '#'} aria-label="Call driver"><Phone size={15}/></a></div></> : <div className="logistics-tracking-live-empty"><MapPin size={28}/><h2>Live location</h2><p>The active route map will appear after a delivery is selected.</p></div>}</section></div></div></main>; }

function LogisticsEarningsPage({ deliveries, loading }) { const completed = deliveries.filter((item) => item.status === 'DELIVERED'); const active = deliveries.filter((item) => item.status !== 'DELIVERED'); const commission = 450; const total = completed.length * commission; const pending = active.length * commission; const chartValues = [38, 54, 46, 72, 58, 81, 66]; return <main className="logistics-feature-page logistics-earnings-reference-page"><div className="logistics-feature-container"><header className="logistics-earnings-reference-header"><div><Link className="logistics-feature-back" to="/dashboard/logistics"><ChevronRight size={14} /> Dispatch dashboard</Link><p className="logistics-feature-kicker"><Wallet size={14}/> FINANCIAL OVERVIEW</p><h1>Earnings</h1><p>Track your total earnings from every completed delivery.</p></div><select className="logistics-earnings-period" aria-label="Earnings period"><option>This month</option><option>This week</option><option>Last month</option></select></header><section className="logistics-earnings-reference-metrics"><div><span>Total earnings</span><strong>₹{loading ? '—' : total.toLocaleString('en-IN')}</strong><small>from completed deliveries</small></div><div><span>Completed deliveries</span><strong>{loading ? '—' : completed.length}</strong><small>successful handoffs</small></div><div><span>Pending amount</span><strong>₹{loading ? '—' : pending.toLocaleString('en-IN')}</strong><small>from {active.length} active orders</small></div></section><section className="logistics-earnings-reference-grid"><div className="logistics-earnings-chart-card"><div className="logistics-earnings-panel-head"><div><span>EARNINGS OVERVIEW</span><h2>Delivery earnings</h2></div><span className="logistics-earnings-period-label">This month</span></div><div className="logistics-earnings-bars">{chartValues.map((height, index) => <div key={index}><span style={{ height: `${height}%` }}/><small>{['1 Sep', '5 Sep', '10 Sep', '15 Sep', '20 Sep', '25 Sep', '30 Sep'][index]}</small></div>)}</div></div><div className="logistics-earnings-breakdown"><div className="logistics-earnings-panel-head"><div><span>DELIVERY STATUS</span><h2>Current balance</h2></div></div><div className="logistics-earnings-donut"><div><strong>{completed.length + active.length}</strong><small>Total orders</small></div></div><div className="logistics-earnings-breakdown-legend"><span><i className="done"/> Completed <b>{completed.length}</b></span><span><i className="pending"/> Pending <b>{active.length}</b></span></div></div></section><section className="logistics-earnings-history"><div className="logistics-earnings-panel-head"><div><span>RECENT TRANSACTIONS</span><h2>Delivery earnings history</h2></div><Link to="/logistics/my-deliveries">View deliveries <ArrowRight size={13}/></Link></div><div className="logistics-earnings-history-table"><div className="logistics-earnings-history-head"><span>Date</span><span>Order ID</span><span>Amount</span><span>Status</span></div>{completed.slice(0, 6).map((delivery, index) => <div className="logistics-earnings-history-row" key={delivery.id}><span>{`${String(index + 1).padStart(2, '0')} Sep 2026`}</span><strong>FD{delivery.order_id}</strong><b>₹{commission.toLocaleString('en-IN')}</b><em>Completed</em></div>)}{!loading && !completed.length && <EmptyState icon={Wallet} title="No earnings yet" copy="Completed delivery earnings will appear here." />}</div></section></div></main>; }

function EarningsView({ deliveries, loading }) { const completed = deliveries.filter((item) => item.status === 'DELIVERED'); const estimated = completed.length * 450; return <main className="logistics-feature-page"><div className="logistics-feature-container"><FeatureHeader title="Earnings overview" subtitle="See your completed delivery performance at a glance." icon={Wallet} /><div className="logistics-summary-strip logistics-earnings-summary"><div><span>Estimated earnings</span><strong>₹{estimated.toLocaleString('en-IN')}</strong></div><div><span>Completed deliveries</span><strong>{loading ? '—' : completed.length}</strong></div><div><span>Average per delivery</span><strong>₹450</strong></div><div><span>On-time rate</span><strong>{completed.length ? '96%' : '—'}</strong></div></div><section className="logistics-feature-list">{completed.map((delivery) => <article className="logistics-feature-row" key={delivery.id}><div className="logistics-feature-row-icon"><Wallet size={18} /></div><div className="logistics-feature-row-main"><div className="logistics-feature-row-top"><span>ORDER FD{delivery.order_id}</span><b className="logistics-status-pill status-delivered">COMPLETED</b></div><h2>{delivery.pickup_location} <ChevronRight size={15} /> {delivery.destination}</h2><p>{delivery.driver?.full_name || 'Dispatch crew'} · Delivery commission</p></div><strong className="logistics-earning-amount">₹450</strong></article>)}{!loading && !completed.length && <EmptyState icon={Wallet} title="No completed deliveries yet" copy="Your earnings history will appear here after the first successful handoff." />}</section></div></main>; }

function NotificationsView({ items, loading, onReload }) { const [localItems, setLocalItems] = useState(items); useEffect(() => setLocalItems(items), [items]); async function read(item) { try { await markNotificationRead(item.id); setLocalItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, is_read: true } : entry)); } catch (_) { } } return <main className="logistics-feature-page"><div className="logistics-feature-container"><FeatureHeader title="Notifications" subtitle="Stay current on assignments and route changes." icon={Bell} action={<button type="button" className="logistics-refresh" onClick={onReload}><RefreshCw size={15} /> Refresh</button>} /><section className="logistics-notification-list">{loading ? <div className="logistics-feature-loading" /> : localItems.map((item) => <button type="button" className={`logistics-notification-row ${item.is_read ? '' : 'is-unread'}`} onClick={() => read(item)} key={item.id}><span><Bell size={16} /></span><div><strong>{item.title}</strong><p>{item.message}</p></div><small>{item.is_read ? 'Read' : 'New'}</small></button>)}{!loading && !localItems.length && <EmptyState icon={Bell} title="You are all caught up" copy="Dispatch notifications will appear here." />}</section></div></main>; }

function SettingsView({ onNotice, notice }) { const [passwords, setPasswords] = useState({ current_password: '', new_password: '' }); const [preferences, setPreferences] = useState(() => JSON.parse(localStorage.getItem('farmdirect_logistics_preferences') || '{"assignment_alerts":true,"route_reminders":true}')); async function submit(event) { event.preventDefault(); try { await changePassword(passwords.current_password, passwords.new_password); setPasswords({ current_password: '', new_password: '' }); onNotice('Password updated successfully.'); } catch (error) { onNotice(error instanceof Error ? error.message : 'Unable to update password'); } } function toggle(key) { const next = { ...preferences, [key]: !preferences[key] }; setPreferences(next); localStorage.setItem('farmdirect_logistics_preferences', JSON.stringify(next)); onNotice('Dispatch preferences saved.'); } return <main className="logistics-feature-page"><div className="logistics-feature-container"><FeatureHeader title="Workspace settings" subtitle="Manage account security and dispatch preferences." icon={Settings} />{notice && <p className="logistics-feature-notice" role="status"><ShieldCheck size={15} />{notice}</p>}<div className="logistics-settings-grid"><section className="logistics-settings-card"><LockKeyhole size={20} /><h2>Change password</h2><p>Keep your dispatch account protected with a strong password.</p><form onSubmit={submit}><input type="password" placeholder="Current password" required value={passwords.current_password} onChange={(event) => setPasswords({ ...passwords, current_password: event.target.value })} /><input type="password" minLength="8" placeholder="New password" required value={passwords.new_password} onChange={(event) => setPasswords({ ...passwords, new_password: event.target.value })} /><button className="logistics-primary-button" type="submit">Update password</button></form></section><section className="logistics-settings-card"><ShieldCheck size={20} /><h2>Dispatch preferences</h2><p>Operational defaults for your FarmDirect workspace.</p><label className="logistics-toggle"><span><strong>Assignment alerts</strong><small>Notify me when a delivery is assigned.</small></span><input type="checkbox" checked={preferences.assignment_alerts} onChange={() => toggle('assignment_alerts')} /></label><label className="logistics-toggle"><span><strong>Route reminders</strong><small>Keep upcoming handoffs visible.</small></span><input type="checkbox" checked={preferences.route_reminders} onChange={() => toggle('route_reminders')} /></label></section></div></div></main>; }

function EmptyState({ icon: Icon, title, copy }) { return <div className="logistics-feature-empty"><Icon size={28} /><h2>{title}</h2><p>{copy}</p></div>; }
